1	import { create } from "zustand";
2	import {
3	  Document,
4	  DocumentFileOps,
5	  DocumentInput,
6	  DocumentSavePayload,
7	  mapDocumentFromDB,
8	} from "@/types/document";
9	import { TreeService } from "@/services/TreeService";
10	import { activeTreeId, isActiveTree } from "@/hooks/useTreeStore";
11	import { useStorageStore } from "@/hooks/useStorageStore";
12	import { invalidateActivityView } from "@/hooks/invalidateDerivedViews";
13	
14	const NO_OPS: DocumentFileOps = {
15	  addedFiles: [],
16	  addedLinks: [],
17	  removedIds: [],
18	  renamed: [],
19	};
20	
21	interface DocumentState {
22	  documents: Document[];
23	  initialized: boolean;
24	  refreshDocuments: (treeId?: string) => Promise<void>;
25	  getDocumentsForMember: (memberId: string) => Document[];
26	  addDocument: (
27	    input: DocumentInput,
28	    memberIds: string[],
29	    fileOps?: DocumentFileOps,
30	    onFileProgress?: (uploaded: number, total: number) => void,
31	  ) => Promise<Document | null>;
32	  updateDocument: (
33	    id: string,
34	    input: DocumentInput,
35	    memberIds: string[],
36	    fileOps?: DocumentFileOps,
37	    onFileProgress?: (uploaded: number, total: number) => void,
38	  ) => Promise<void>;
39	  removeDocument: (id: string) => Promise<void>;
40	  clear: () => void;
41	}
42	
43	/** Stream the picked files into the staging area (reporting per-file progress)
44	 *  and build the atomic save payload referencing them. New files are staged
45	 *  *before* the save runs — and the save removes old files only after it
46	 *  commits — so a failed save never destroys the previous version. */
47	async function stageAndBuildPayload(
48	  treeId: string,
49	  input: DocumentInput,
50	  memberIds: string[],
51	  ops: DocumentFileOps,
52	  onFileProgress?: (uploaded: number, total: number) => void,
53	): Promise<DocumentSavePayload> {
54	  const total = ops.addedFiles.length;
55	  if (total > 0) onFileProgress?.(0, total);
56	  const attachedUploadIds: string[] = [];
57	  for (const [i, f] of ops.addedFiles.entries()) {
58	    const staged = await TreeService.stageDocumentUpload(
59	      treeId,
60	      f.file,
61	      f.filename,
62	    );
63	    attachedUploadIds.push(staged.id);
64	    onFileProgress?.(i + 1, total);
65	  }
66	  return {
67	    title: input.title,
68	    description: input.description || null,
69	    document_date: input.documentDate || null,
70	    member_ids: memberIds,
71	    attached_upload_ids: attachedUploadIds,
72	    added_links: ops.addedLinks.map((l) => ({
73	      id: crypto.randomUUID(),
74	      url: l.url,
75	      filename: l.label ?? null,
76	    })),
77	    removed_file_ids: ops.removedIds,
78	    renamed_files: ops.renamed,
79	  };
80	}
81	
82	/** Whether a save changes on-disk media, so callers can refresh storage usage. */
83	function touchesMedia(ops: DocumentFileOps): boolean {
84	  return ops.addedFiles.length > 0 || ops.removedIds.length > 0;
85	}
86	
87	export const useDocumentStore = create<DocumentState>((set, get) => ({
88	  documents: [],
89	  initialized: false,
90	
91	  refreshDocuments: async (treeId = activeTreeId()) => {
92	    if (!treeId) {
93	      set({ documents: [] });
94	      return;
95	    }
96	
97	    const rows = await TreeService.getDocuments(treeId);
98	
99	    if (!isActiveTree(treeId)) return; // tree switched/disconnected mid-flight
100	
101	    set({ documents: rows.map(mapDocumentFromDB), initialized: true });
102	  },
103	
104	  getDocumentsForMember: (memberId: string) => {
105	    return get().documents.filter((d) => d.memberIds.includes(memberId));
106	  },
107	
108	  addDocument: async (
109	    input: DocumentInput,
110	    memberIds: string[],
111	    fileOps: DocumentFileOps = NO_OPS,
112	    onFileProgress?: (uploaded: number, total: number) => void,
113	  ) => {
114	    const treeId = activeTreeId();
115	    if (!treeId) return null;
116	
117	    // Stage the files, then create the document with its metadata, people
118	    // links and attachments in one atomic request. A client-generated id makes
119	    // a retried create upsert instead of duplicating; a failure leaves nothing
120	    // behind, so there is no orphaned row to roll back.
121	    const documentId = crypto.randomUUID();
122	    const payload = await stageAndBuildPayload(
123	      treeId,
124	      input,
125	      memberIds,
126	      fileOps,
127	      onFileProgress,
128	    );
129	    const row = await TreeService.saveDocument(treeId, documentId, payload);
130	
131	    await get().refreshDocuments(treeId);
132	    if (touchesMedia(fileOps)) useStorageStore.getState().refreshStorageUsage();
133	    invalidateActivityView();
134	    return mapDocumentFromDB(row);
135	  },
136	
137	  updateDocument: async (
138	    id: string,
139	    input: DocumentInput,
140	    memberIds: string[],
141	    fileOps: DocumentFileOps = NO_OPS,
142	    onFileProgress?: (uploaded: number, total: number) => void,
143	  ) => {
144	    const treeId = activeTreeId();
145	    if (!treeId) return;
146	
147	    // Stage new files first, then apply the metadata, member and file changes
148	    // in one atomic request; old files are removed only once it commits, so a
149	    // failed edit leaves the previous valid document untouched.
150	    const payload = await stageAndBuildPayload(
151	      treeId,
152	      input,
153	      memberIds,
154	      fileOps,
155	      onFileProgress,
156	    );
157	    await TreeService.saveDocument(treeId, id, payload);
158	
159	    await get().refreshDocuments(treeId);
160	    if (touchesMedia(fileOps)) useStorageStore.getState().refreshStorageUsage();
161	    invalidateActivityView();
162	  },
163	
164	  removeDocument: async (id: string) => {
165	    const treeId = activeTreeId();
166	    if (!treeId) return;
167	
168	    await TreeService.removeDocument(treeId, id);
169	    await get().refreshDocuments(treeId);
170	    useStorageStore.getState().refreshStorageUsage();
171	    invalidateActivityView();
172	  },
173	
174	  clear: () => set({ documents: [], initialized: false }),
175	}));
